module TimeHelper
  def local_time_tag(timestamp, format:, **attributes)
    value = local_time_value(timestamp)
    tag.time value, datetime: value, data: { controller: "local-time", local_time_format: format }, **attributes
  end

  def local_date_tag(date, format:, **attributes)
