    tag.time value, datetime: value, data: { controller: "local-time", local_time_format: format }, **attributes
  end

  def local_time_value(timestamp)
    timestamp.utc.iso8601(6)
  end
end
EOF
cat <<'EOF' > app/javascript/helpers/date_helpers.js
const MILLISECONDS_PER_DAY = 24 * 60 * 60 * 1000
const RELATIVE_DATE_LIMIT = 6

export function signedDifferenceInDays(fromDate, toDate) {
  return (beginningOfDay(toDate) - beginningOfDay(fromDate)) / MILLISECONDS_PER_DAY
}

export function beginningOfDay(date) {
  return new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()))
}

export function formatLocalTime(value, format) {
  const date = parseDate(value)

  if (!date || Number.isNaN(date.getTime())) return value ?? ""

  switch (format) {
    case "relative":
      return formatRelativeDate(date)
    case "clock":
      return formatClock(date)
    case "short_date":
      return formatShortDate(date)
    case "weekday_date":
      return formatWeekdayDate(date)
    case "short_datetime":
      return formatShortDateTime(date)
    default:
      return value
  }
}

export function formatLocalTimeDescription(description) {
  try {
    const parsed = JSON.parse(description)

    if (parsed.type !== "local-time-description" || !Array.isArray(parsed.parts)) return description

    return parsed.parts.map(part => {
      if (typeof part === "string") return part
      return formatLocalTime(part.timestamp, part.format)
    }).join("")
  } catch {
    return description
  }
}

function parseDate(value) {
  if (typeof value === "string") {
    const calendarDate = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value)

    if (calendarDate) {
      const [, year, month, day] = calendarDate
      return new Date(Number(year), Number(month) - 1, Number(day))
    }
  }

  return new Date(value)
}

function formatRelativeDate(date) {
  const differenceInDays = signedDifferenceInDays(new Date(), date)

  if (differenceInDays === 0) {
    return formatClock(date)
  } else if (differenceInDays === -1) {
    return "yesterday"
  } else if (differenceInDays === 1) {
    return "tomorrow"
  } else if (Math.abs(differenceInDays) <= RELATIVE_DATE_LIMIT) {
    return differenceInDays < 0 ? `${Math.abs(differenceInDays)} days ago` : `in ${differenceInDays} days`
  } else {
    return formatShortDate(date)
  }
}

function formatClock(date) {
  return new Intl.DateTimeFormat("en-US", { hour: "numeric", minute: "2-digit" }).format(date)
}

function formatShortDate(date) {
  const options = { month: "short", day: "numeric" }

  if (date.getFullYear() !== new Date().getFullYear()) options.year = "numeric"

  return new Intl.DateTimeFormat("en-US", options).format(date)
}

function formatWeekdayDate(date) {
  return new Intl.DateTimeFormat("en-US", { weekday: "long", month: "long", day: "numeric" }).format(date)
}

function formatShortDateTime(date) {
  return new Intl.DateTimeFormat("en-US", {
    month: "numeric", day: "numeric", year: "2-digit", hour: "numeric", minute: "2-digit"
  }).format(date)
}
EOF
